SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.NAME AS oblname, Имена_станций.ordnumb, Станции2018.Year, Станции2018.NUST, Станции2018.nr, Станции2018.E, Станции2018.EOTP, Станции2018.EURT, Станции2018.EUST, Станции2018.Q, Станции2018.TURT, Станции2018.TUST, Станции2018.B, Станции2018.GAZ, Доп_угли2018.gazpp, Станции2018.MAZUT, Станции2018.TORF, Станции2018.SLAN, Станции2018.PROCH, Доп_угли2018.koksdom, Доп_угли2018.prochgaz, Доп_угли2018.tvproch, Станции2018.UGOL, Станции2018.DON, Станции2018.PODM, Станции2018.PECH, Доп_угли2018.intin, Доп_угли2018.vork, Станции2018.ARKT, Станции2018.KUZN, Доп_угли2018.kuzngd, Доп_угли2018.kuznt, Доп_угли2018.kuznss, Доп_угли2018.kuznun, Станции2018.URAL, Доп_угли2018.sver, Доп_угли2018.chel, Доп_угли2018.kizel, Станции2018.BASHK, Станции2018.KAZAH, Доп_угли2018.ekib, Доп_угли2018.maikub, Станции2018.KAN, Доп_угли2018.nazar, Доп_угли2018.ibor, Доп_угли2018.berez, Доп_угли2018.per, Доп_угли2018.irbei, Доп_угли2018.kansk, Станции2018.TUNG, Доп_угли2018.jer, Доп_угли2018.karab, Станции2018.IRKUT, Доп_угли2018.azey, Доп_угли2018.mug, Доп_угли2018.cher, Станции2018.HAK, Станции2018.TUV, Станции2018.BUR, Доп_угли2018.gusin, Доп_угли2018.tugn, Доп_угли2018.okino, Станции2018.CHIT, Доп_угли2018.har, Доп_угли2018.urt, Доп_угли2018.tataur, Доп_угли2018.tarbag, Доп_угли2018.zab_kam, Станции2018.YAKUT, Доп_угли2018.neru, Доп_угли2018.zyryan, Доп_угли2018.pyak, Станции2018.AMUR, Доп_угли2018.rai, Доп_угли2018.erk, Станции2018.URG, Станции2018.USHUM, Станции2018.PRIM, Доп_угли2018.bikin, Доп_угли2018.razdol, Доп_угли2018.hankai, Станции2018.MAG, Станции2018.SAH, Станции2018.KAMCH, Станции2018.CHUKOT, Доп_угли2018.anad, Доп_угли2018.bering, Станции2018.QOTR, Станции2018.SNK, Станции2018.EWTP, Станции2018.NT, Станции2018.OBOR, Станции2018.VED, Станции2018.OBL, Станции2018.DEP, Станции2018.OES, Станции2018.ER, Станции2018.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Имена_станций.GK, Имена_станций.BE, имена_ГК.name AS namegk, [Филиалы ГК].name AS filial, имена_БЕ.name AS namebe, Города.Name AS Town, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"Дет",IIf([obor]=24,"ГПА","ПСУ"))))) AS тип, Станции2018.SNt, Имена_станций.n1 AS [мощность блока]
FROM ((((Имена_станций LEFT JOIN Города ON Имена_станций.codegor = Города.code) INNER JOIN (Имена_областей INNER JOIN (Имена_ОЭС INNER JOIN (Станции2018 LEFT JOIN Доп_угли2018 ON (Станции2018.NUMB1120 = Доп_угли2018.NUMB1120) AND (Станции2018.YEAR = Доп_угли2018.YEAR)) ON Имена_ОЭС.oes = Станции2018.OES) ON Имена_областей.OBL = Станции2018.OBL) ON Имена_станций.NUMB = Станции2018.NUMB1120) LEFT JOIN имена_ГК ON Имена_станций.GK = имена_ГК.code) LEFT JOIN имена_БЕ ON Имена_станций.BE = имена_БЕ.code) INNER JOIN [Филиалы ГК] ON Имена_станций.GKF = [Филиалы ГК].code;
